<form method="GET" class="card card-body mb-3"><div class="form-row"><div class="col-md-2"><select name="period" class="form-control"><option value="today" @selected($f['period']==='today')>Hoy</option><option value="yesterday" @selected($f['period']==='yesterday')>Ayer</option><option value="week" @selected($f['period']==='week')>Esta semana</option><option value="month" @selected($f['period']==='month')>Este mes</option><option value="previous_month" @selected($f['period']==='previous_month')>Mes anterior</option><option value="custom" @selected($f['period']==='custom')>Rango personalizado</option></select></div><div class="col-md-2"><input type="date" name="from" value="{{$f['from']}}" class="form-control"></div><div class="col-md-2"><input type="date" name="to" value="{{$f['to']}}" class="form-control"></div><div class="col-auto"><button class="btn btn-primary">Aplicar</button></div></div></form>
